from pathlib import Path
root=Path(__file__).parent
checks=[]
def check(name,ok): checks.append((name,bool(ok)))
entity=(root/'src/ads/ad.entity.ts').read_text();service=(root/'src/ads/ads.service.ts').read_text();controller=(root/'src/ads/ads.controller.ts').read_text();module=(root/'src/ads/ads.module.ts').read_text();migration=(root/'src/database/migrations/1732900000000-CreateAdvertisements.ts').read_text();app=(root/'src/app.module.ts').read_text();ds=(root/'src/database/data-source.ts').read_text();client=(root/'mobile/src/api/client.ts').read_text();owner=(root/'mobile/src/screens/OwnerAdsScreen.tsx').read_text();home=(root/'mobile/src/screens/HomeScreen.tsx').read_text();search=(root/'mobile/src/screens/SearchScreen.tsx').read_text();nav=(root/'mobile/App.tsx').read_text();dashboard=(root/'mobile/src/screens/ProviderDashboardScreen.tsx').read_text();docs=(root/'docs/phase-v36-advertising-and-revenue.md').read_text()
check('ad entity stores advertiser and creative fields',all(x in entity for x in ['advertiserName','title','description','imageUrl','targetUrl']))
check('ad entity stores placements and lifecycle',all(x in entity for x in ['AdPlacement','AdStatus','HOME','SEARCH','DRAFT','ACTIVE','PAUSED','ENDED']))
check('ad entity stores schedule and IQD amounts',all(x in entity for x in ['startsAt','endsAt','priceIqd','paidAmountIqd','paymentReference']))
check('ad entity stores engagement counters',all(x in entity for x in ['impressions','clicks']))
check('owner-only management controller protected by JWT and role',"@Controller('owner/ads')" in controller and '@UseGuards(JwtAuthGuard,RolesGuard)' in controller and '@Roles(UserRole.OWNER)' in controller)
check('public active ad feed is date and placement filtered','publicAds' in service and 'startsAt' in service and 'endsAt' in service and 'placement' in service)
check('public feed exposes only display-safe fields',"'a.targetUrl'" in service and "'a.id'" in service)
check('impression and click counters only count active in-range ads',"status:AdStatus.ACTIVE" in service and "kind==='impression'?'impressions':'clicks'" in service)
check('ad create validates schedule, payment cap and starts as draft','end<=start' in service and 'status:AdStatus.DRAFT' in service and 'paidAmountIqd??0)>dto.priceIqd' in service)
check('expired campaigns are closed before owner reports','private async expireDue()' in service and 'await this.expireDue()' in service)
check('owner can update and manage campaign state',"@Patch(':id')" in controller and 'status?:AdStatus' in (root/'src/ads/dto/update-ad.dto.ts').read_text())
check('report includes contracted and collected revenue','contractedRevenueIqd' in service and 'collectedRevenueIqd' in service and 'outstandingIqd' in service)
check('report includes ad engagement','impressions:Number' in service and 'clicks:Number' in service)
check('ad operations write owner audit records',"targetType:'advertisement'" in service and "'ad_created'" in service and "'ad_updated'" in service)
check('migration creates advertisement table and indexes','CREATE TABLE "advertisements"' in migration and 'ix_advertisements_status_dates' in migration and 'ix_advertisements_placement_status' in migration)
check('advertisement entity registered in runtime and migrations', 'Advertisement' in app and 'AdsModule' in app and 'Advertisement' in ds)
check('ads module registered with repositories and controllers','Advertisement' in module and 'PublicAdsController' in module and 'OwnerAdsController' in module)
check('mobile API supports public feed and engagement','publicAds:' in client and 'recordAdImpression:' in client and 'recordAdClick:' in client)
check('mobile API supports owner ads and reporting','ownerAds:' in client and 'ownerAdReport:' in client and 'createOwnerAd:' in client and 'updateOwnerAd:' in client)
check('owner mobile screen creates and manages campaigns','createOwnerAd' in owner and 'تفعيل الإعلان' in owner and 'إيقاف مؤقت' in owner)
check('owner mobile screen displays financial metrics','collectedRevenueIqd' in owner and 'outstandingIqd' in owner and 'contractedRevenueIqd' in owner)
check('owner dashboard navigates to ad management','onManageAds' in dashboard and 'OwnerAds' in nav)
check('patient home displays active home ads','publicAds(\'home\')' in home and 'recordAdImpression' in home and 'recordAdClick' in home)
check('search screen displays active search ads','publicAds(\'search\')' in search and 'recordAdImpression' in search and 'recordAdClick' in search)
check('documentation discloses manual payment and migration','migration' in docs.lower() and 'manual' in docs.lower() and 'No APK' in docs)
for n,o in checks: print(('PASS' if o else 'FAIL')+' '+n)
print(f'V36: {sum(o for _,o in checks)}/{len(checks)}')
raise SystemExit(0 if all(o for _,o in checks) else 1)
